<template>
  <div class="page-shell">
    <div class="page-title-row"><div><h1 class="page-title">风险告警中心</h1><p class="page-subtitle">对仓储、库存、交通、气象与区域供应风险进行统一分级、查询、核验和状态流转</p></div><div class="toolbar"><el-button @click="load"><el-icon><Refresh/></el-icon>刷新</el-button><el-button v-if="auth.isDispatcher" type="primary" class="gs-gradient-button" :loading="scanning" @click="scan"><el-icon><Aim/></el-icon>执行风险扫描</el-button></div></div>
    <div class="glass-card alert-card">
      <div class="filter-row"><el-select v-model="filters.level" clearable placeholder="风险等级" style="width:150px"><el-option v-for="o in levels" :key="o.value" v-bind="o"/></el-select><el-select v-model="filters.riskType" clearable placeholder="风险类型" style="width:170px"><el-option v-for="o in types" :key="o.value" v-bind="o"/></el-select><el-select v-model="filters.status" clearable placeholder="处理状态" style="width:150px"><el-option v-for="o in statuses" :key="o.value" v-bind="o"/></el-select><el-input v-model="keyword" clearable prefix-icon="Search" placeholder="搜索告警编号、节点或内容" style="width:260px"/></div>
      <el-table :data="filtered" v-loading="loading" height="calc(100vh - 280px)" stripe>
        <el-table-column prop="code" label="告警编号" width="175" fixed/>
        <el-table-column label="等级" width="85"><template #default="s"><StatusTag :value="s.row.level"/></template></el-table-column>
        <el-table-column prop="riskType" label="风险类型" width="120"><template #default="s">{{typeMap[s.row.riskType]||s.row.riskType}}</template></el-table-column>
        <el-table-column prop="nodeName" label="影响节点" width="170"><template #default="s">{{s.row.nodeName||'-'}}</template></el-table-column>
        <el-table-column prop="routeName" label="影响线路" width="180"><template #default="s">{{s.row.routeName||'-'}}</template></el-table-column>
        <el-table-column prop="detail" label="触发详情" min-width="300" show-overflow-tooltip/>
        <el-table-column label="状态" width="95"><template #default="s"><StatusTag :value="s.row.status"/></template></el-table-column>
        <el-table-column prop="alarmTime" label="触发时间" width="175"><template #default="s">{{fmt(s.row.alarmTime)}}</template></el-table-column>
        <el-table-column label="操作" width="265" fixed="right"><template #default="s"><el-button link type="primary" @click="show(s.row)">详情</el-button><template v-if="auth.isDispatcher"><el-dropdown @command="c=>handle(s.row,c)"><el-button link type="primary">处理<el-icon><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="CONFIRMED">确认告警</el-dropdown-item><el-dropdown-item command="IGNORED">忽略告警</el-dropdown-item><el-dropdown-item command="CLOSED">关闭告警</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button link type="success" :disabled="s.row.status==='CLOSED'||s.row.status==='IGNORED'" @click="analyze(s.row)">调度分析</el-button></template></template></el-table-column>
      </el-table>
    </div>
    <el-drawer v-model="drawer" title="告警详情" size="480px"><template v-if="current"><div class="alert-hero" :class="current.level?.toLowerCase()"><StatusTag :value="current.level"/><h3>{{current.code}}</h3><p>{{current.detail}}</p></div><el-descriptions :column="1" border><el-descriptions-item label="风险类型">{{typeMap[current.riskType]}}</el-descriptions-item><el-descriptions-item label="影响节点">{{current.nodeName||'-'}}</el-descriptions-item><el-descriptions-item label="影响线路">{{current.routeName||'-'}}</el-descriptions-item><el-descriptions-item label="处理状态"><StatusTag :value="current.status"/></el-descriptions-item><el-descriptions-item label="触发规则">{{current.ruleName||'-'}}</el-descriptions-item><el-descriptions-item label="建议措施">{{current.suggestion}}</el-descriptions-item><el-descriptions-item label="触发时间">{{fmt(current.alarmTime)}}</el-descriptions-item><el-descriptions-item label="处理人">{{current.handledBy||'-'}}</el-descriptions-item></el-descriptions><el-button v-if="auth.isDispatcher" type="primary" class="drawer-action gs-gradient-button" @click="analyze(current)">转入应急调度建议分析</el-button></template></el-drawer>
  </div>
</template>
<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import api from '../api/client';import StatusTag from '../components/StatusTag.vue';import { useAuthStore } from '../stores/auth';const auth=useAuthStore(),router=useRouter();const rows=ref([]),loading=ref(false),scanning=ref(false),drawer=ref(false),current=ref(null),keyword=ref('');const filters=reactive({level:null,riskType:null,status:null});
const levels=[{value:'LOW',label:'低风险'},{value:'MEDIUM',label:'中风险'},{value:'HIGH',label:'高风险'},{value:'CRITICAL',label:'紧急风险'}],types=[{value:'INVENTORY',label:'库存不足'},{value:'TEMPERATURE',label:'温度异常'},{value:'HUMIDITY',label:'湿度异常'},{value:'TRAFFIC',label:'交通阻断'},{value:'WEATHER',label:'气象灾害'},{value:'REGIONAL_SUPPLY',label:'区域供应'}],statuses=[{value:'NEW',label:'待处理'},{value:'CONFIRMED',label:'已确认'},{value:'ANALYZING',label:'分析中'},{value:'IGNORED',label:'已忽略'},{value:'CLOSED',label:'已关闭'}];const typeMap=Object.fromEntries(types.map(x=>[x.value,x.label]));const filtered=computed(()=>{let a=rows.value;if(filters.level)a=a.filter(x=>x.level===filters.level);if(filters.riskType)a=a.filter(x=>x.riskType===filters.riskType);if(filters.status)a=a.filter(x=>x.status===filters.status);const k=keyword.value.toLowerCase().trim();if(k)a=a.filter(x=>JSON.stringify(x).toLowerCase().includes(k));return a});const fmt=v=>v?.replace('T',' ').slice(0,19)||'-';
async function load(){loading.value=true;try{rows.value=await api.get('/alerts')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}async function scan(){scanning.value=true;try{const r=await api.post('/alerts/scan');ElMessage.success(`扫描 ${r.scannedRules} 条规则，新增 ${r.generatedAlerts} 条告警`);await load()}catch(e){ElMessage.error(e.message)}finally{scanning.value=false}}async function handle(row,status){try{await api.put(`/alerts/${row.id}/status`,{status});ElMessage.success('告警状态已更新');await load()}catch(e){ElMessage.error(e.message)}}function show(row){current.value=row;drawer.value=true}function analyze(row){drawer.value=false;router.push({path:'/dispatch',query:{alertId:row.id}})}onMounted(load)
</script>
<style scoped>.alert-card{overflow:hidden}.filter-row{padding:17px 20px;display:flex;gap:10px;flex-wrap:wrap;border-bottom:1px solid #edf2ef}.alert-hero{padding:20px;border-radius:16px;background:#f4f8f6;margin-bottom:18px;border-left:5px solid #6e9b89}.alert-hero.high,.alert-hero.critical{background:#fff5f4;border-color:#d95757}.alert-hero h3{margin:12px 0 8px;color:#213c32}.alert-hero p{margin:0;color:#60736c;line-height:1.75}.drawer-action{width:100%;margin-top:20px}</style>
